// pool simples
const { Worker } = require('worker_threads');
const os = require('os');
const fila = []; const livres = [];
for (let i = 0; i < os.availableParallelism(); i++) livres.push(new Worker('./gerar-relatorio.js'));
function executar(payload) {
  return new Promise((res, rej) => {
    const w = livres.pop();
    if (!w) return fila.push({ payload, res, rej });
    w.once('message', m => { livres.push(w); res(m); const n = fila.shift(); if (n) executar(n.payload).then(n.res, n.rej); });
    w.once('error', rej);
    w.postMessage(payload);
  });
}
