let encerrando = false;
async function shutdown(code = 0) {
  if (encerrando) return; encerrando = true;
  setTimeout(() => process.exit(1), 15_000).unref();   // trava de segurança
  app.set('saudavel', false);                          // /health passa a responder 503 → balanceador tira da rotação
  server.close(async () => {
    await filaConsumer.stop();
    await pool.end();                                  // devolve conexões ao PG
    process.exit(code);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 5_000).unref();
}
process.on('SIGTERM', () => shutdown(0));
process.on('SIGINT', () => shutdown(0));
